parameters.functionCode:
const input = $input.first().json;
const body = input.body || input;

const requestTypes = ['access', 'deletion', 'portability', 'rectification', 'restriction'];
const requestType = body.request_type;

if (!requestTypes.includes(requestType)) return [{ json: { error: true, message: 'Invalid request type' } }];
if (!body.email) return [{ json: { error: true, message: 'Email required' } }];

const requestId = `DSR-${Date.now().toString(36).toUpperCase()}`;

return [{ json: {
  request_id: requestId,
  request_type: requestType,
  email: body.email,
  requester_name: body.name || '',
  reason: body.reason || '',
  client_id: body.client_id,
  deadline: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // 30 days GDPR deadline
}}];

